"use client"

import { Header } from "@/components/header"
import { Footer } from "@/components/footer"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Phone, Volume2, PlayCircle, StopCircle, PhoneCall, Info, Settings } from "lucide-react"
import { useState, useEffect } from "react"
import dynamic from "next/dynamic"
import { useLanguage } from "@/lib/i18n/language-context"
import { languages } from "@/lib/i18n/translations"

// Code splitting for heavy components
const MarketWomanMode = dynamic(() => import("@/components/market-woman-mode").then(mod => ({ default: mod.MarketWomanMode })), {
  loading: () => <div className="h-64 flex items-center justify-center"><div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div></div>,
  ssr: false
})

export default function VoiceAssistantPage() {
  const { language, setLanguage, isMarketWomanMode, setMarketWomanMode, t } = useLanguage()
  const [currentRate, setCurrentRate] = useState<number | null>(null)
  const [loading, setLoading] = useState(true)
  const [playing, setPlaying] = useState(false)

  useEffect(() => {
    fetch("/api/rates/live")
      .then((res) => res.json())
      .then((data) => {
        if (data.rate && typeof data.rate === "number") {
          setCurrentRate(data.rate)
        }
        setLoading(false)
      })
      .catch((err) => {
        console.error("[v0] Error fetching rate:", err)
        setLoading(false)
      })
  }, [])

  const speakRate = () => {
    if ("speechSynthesis" in window && currentRate) {
      setPlaying(true)
      const text = language === 'lr-en'
        ? `Dollar rate now: ${currentRate.toFixed(0)} LD.`
        : `Today's exchange rate is 1 U.S. Dollar equals ${currentRate.toFixed(2)} Liberian Dollars.`
      
      const utterance = new SpeechSynthesisUtterance(text)
      utterance.lang = "en-US"
      utterance.rate = language === 'lr-en' ? 0.85 : 1
      utterance.onend = () => setPlaying(false)
      window.speechSynthesis.speak(utterance)
    }
  }

  const stopSpeaking = () => {
    if ("speechSynthesis" in window) {
      window.speechSynthesis.cancel()
      setPlaying(false)
    }
  }

  return (
    <div className="min-h-screen flex flex-col">
      <Header />
      <main className="flex-1">
        {/* Hero Section */}
        <section className="py-12 sm:py-14 md:py-16 bg-gradient-to-b from-primary/10 to-background">
          <div className="container mx-auto px-4">
            <div className="max-w-4xl mx-auto text-center">
              <div className="flex justify-center mb-4">
                <div className="h-16 w-16 rounded-full bg-primary/20 flex items-center justify-center">
                  <Volume2 className="h-8 w-8 text-primary" />
                </div>
              </div>
              <div className="flex flex-wrap items-center justify-center gap-2 mb-4">
                <Badge className="mb-2">Voice Assistant</Badge>
                <Badge className="bg-primary/10 text-primary">Audio Access</Badge>
                <Badge variant="secondary">No Internet Needed</Badge>
                <Badge className="bg-green-50 text-green-700 dark:bg-green-950 dark:text-green-400">Market Friendly</Badge>
              </div>
              <h1 className="text-3xl sm:text-4xl md:text-5xl font-bold mb-6 text-balance">
                <span className="bg-gradient-to-r from-primary via-secondary to-primary bg-clip-text text-transparent">
                  {isMarketWomanMode ? t('simple.mode') : 'Voice Assistant'}
                </span>
              </h1>
              <p className="text-base sm:text-lg text-muted-foreground text-pretty max-w-3xl mx-auto">
                {isMarketWomanMode
                  ? t('simple.modeDesc') + ' - Perfect for Waterside, Red Light, Duala markets'
                  : 'Listen to today\'s exchange rates - perfect for users who prefer audio information'
                }
              </p>
            </div>
          </div>
        </section>

        <section className="py-6 sm:py-8 bg-background">
          <div className="container mx-auto px-4">
            <div className="max-w-4xl mx-auto space-y-6">
              <div className="text-center mb-8 space-y-3">
                <div className="flex flex-wrap items-center justify-center gap-2 mb-2">
                  <Badge variant="outline">Voice Features</Badge>
                  <Badge className="bg-primary/10 text-primary">Audio Access</Badge>
                  <Badge variant="secondary">Multiple Languages</Badge>
                </div>
                <h2 className="text-2xl sm:text-3xl font-bold text-balance">
                  <span className="bg-gradient-to-r from-primary via-secondary to-primary bg-clip-text text-transparent">
                    Audio Rate Information
                  </span>
                </h2>
                <p className="text-sm sm:text-base text-muted-foreground">
                  Voice features designed for Liberian users who prefer audio information
                </p>
              </div>
              {/* Mode Toggle */}
              <Card className="border-primary/20 bg-gradient-to-br from-primary/5 to-card shadow-sm">
                <CardContent className="py-4">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <div className="h-10 w-10 rounded-lg bg-primary/10 flex items-center justify-center">
                        <Settings className="h-5 w-5 text-primary" />
                      </div>
                      <div>
                        <div className="font-semibold text-primary">{t('simple.mode')}</div>
                        <div className="text-sm text-muted-foreground">
                          Big numbers, voice readout - easy for everyone
                        </div>
                      </div>
                    </div>
                    <Button
                      variant={isMarketWomanMode ? "default" : "outline"}
                      onClick={() => setMarketWomanMode(!isMarketWomanMode)}
                      className="shadow-sm"
                    >
                      {isMarketWomanMode ? 'ON' : 'OFF'}
                    </Button>
                  </div>
                </CardContent>
              </Card>

              {/* Market Woman Mode - Full Screen Rate */}
              {isMarketWomanMode ? (
                <MarketWomanMode />
              ) : (
                <>
                  {/* Regular Audio Player */}
                  <Card className="mb-6">
                    <CardContent className="pt-6">
                      <div className="text-center space-y-6">
                        <div className="inline-block">
                          {loading || !currentRate ? (
                            <div className="text-xl font-semibold">Loading rate...</div>
                          ) : (
                            <div>
                              <div className="text-sm text-muted-foreground mb-2">Current Exchange Rate</div>
                              <div className="text-5xl font-bold text-primary">1 USD = {currentRate.toFixed(2)} LRD</div>
                            </div>
                          )}
                        </div>

                        <div className="flex justify-center gap-4">
                          {!playing ? (
                            <Button size="lg" onClick={speakRate} disabled={loading || !currentRate}>
                              <PlayCircle className="h-5 w-5 mr-2" />
                              Play Audio Rate
                            </Button>
                          ) : (
                            <Button size="lg" variant="destructive" onClick={stopSpeaking}>
                              <StopCircle className="h-5 w-5 mr-2" />
                              Stop
                            </Button>
                          )}
                        </div>

                        <Badge variant="secondary" className="text-sm">
                          <Volume2 className="h-3 w-3 mr-1" />
                          Audio updates every minute
                        </Badge>
                      </div>
                    </CardContent>
                  </Card>
                </>
              )}

              {/* IVR Phone Service */}
              <Card className="border-secondary/60 bg-gradient-to-br from-secondary/5 to-card shadow-sm">
                <CardHeader className="pb-4">
                  <div className="flex items-center gap-3">
                    <div className="h-14 w-14 rounded-xl bg-secondary/10 flex items-center justify-center">
                      <Phone className="h-7 w-7 text-secondary" />
                    </div>
                    <div>
                      <CardTitle className="text-secondary">Call for Today's Rate</CardTitle>
                      <CardDescription className="text-secondary/70">IVR phone service available 24/7</CardDescription>
                    </div>
                  </div>
                </CardHeader>
                <CardContent>
                  <div className="space-y-4">
                    <div className="p-6 bg-secondary/10 rounded-lg text-center">
                      <div className="text-sm text-muted-foreground mb-2">Toll-Free Number</div>
                      <div className="text-3xl font-bold text-secondary">1-800-TRUE-RATE</div>
                      <div className="text-sm text-muted-foreground mt-1">(1-800-8783-7283)</div>
                    </div>

                    <div className="space-y-2">
                      <h3 className="font-semibold text-sm">Phone Menu Options:</h3>
                      <div className="grid md:grid-cols-2 gap-2">
                        {[
                          "Press 1: Hear today's USD/LRD rate",
                          "Press 2: Hear yesterday's rate",
                          "Press 3: Weekly rate trend",
                          "Press 4: Find nearby money changers",
                          "Press 5: Report fraud or scam",
                          "Press 0: Speak to support",
                        ].map((option, i) => (
                          <div key={i} className="text-sm p-2 bg-muted rounded">
                            {option}
                          </div>
                        ))}
                      </div>
                    </div>

                    <Button className="w-full" size="lg">
                      <PhoneCall className="h-5 w-5 mr-2" />
                      Call Now
                    </Button>
                  </div>
                </CardContent>
              </Card>

              {/* Language Options */}
              <Card>
                <CardHeader>
                  <CardTitle>Select Language</CardTitle>
                  <CardDescription>Choose your preferred language for the app</CardDescription>
                </CardHeader>
                <CardContent>
                  <div className="grid md:grid-cols-2 gap-3">
                    {languages.map((lang) => (
                      <Button 
                        key={lang.code} 
                        variant={language === lang.code ? "default" : "outline"} 
                        className="justify-start"
                        onClick={() => setLanguage(lang.code)}
                      >
                        <Badge variant="secondary" className="mr-2">
                          {lang.code.toUpperCase()}
                        </Badge>
                        {lang.nativeName}
                      </Button>
                    ))}
                  </div>
                  <div className="mt-4 grid md:grid-cols-3 gap-3">
                    {[
                      { name: "Bassa", code: "BA" },
                      { name: "Gio", code: "GI" },
                      { name: "Mano", code: "MA" },
                      { name: "Kru", code: "KR" },
                    ].map((lang) => (
                      <Button key={lang.code} variant="outline" className="justify-start bg-transparent" disabled>
                        <Badge variant="outline" className="mr-2">
                          {lang.code}
                        </Badge>
                        {lang.name}
                        <span className="text-xs text-muted-foreground ml-auto">Soon</span>
                      </Button>
                    ))}
                  </div>
                </CardContent>
              </Card>

              {/* Info Card */}
              <Card className="bg-gradient-to-br from-amber-500/10 to-accent/10 border-amber-500/30 shadow-sm">
                <CardContent className="pt-6">
                  <div className="flex gap-4">
                    <div className="h-10 w-10 rounded-lg bg-amber-500/10 flex items-center justify-center flex-shrink-0">
                      <Info className="h-5 w-5 text-amber-600" />
                    </div>
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-2">
                        <h3 className="font-semibold text-amber-600">For All Users</h3>
                        <Badge className="bg-amber-100 text-amber-700 dark:bg-amber-950 dark:text-amber-400">Inclusive Access</Badge>
                      </div>
                      <p className="text-sm text-muted-foreground leading-relaxed">
                        {isMarketWomanMode
                          ? 'Market Woman Mode shows one big number with voice. Just tap the screen to hear the rate. Share with your friends at Waterside, Red Light, or Duala markets!'
                          : 'This voice service is designed to help everyone access exchange rate information, regardless of reading ability. Share this number with family and friends who prefer audio information.'
                        }
                      </p>
                    </div>
                  </div>
                </CardContent>
              </Card>
            </div>
          </div>
        </section>
      </main>
      <Footer />
    </div>
  )
}
